AscendancyData.ById = {}
AscendancyData.ByClass = {}
-- (CLASS BUILDS) SIGNATURES: each specialization's one signature rule (List[i].Sig / Build / SigNode; the node has Sig + Build;
-- its Fx { Kind = "Sig", Id, P = numbers, Stats = a timed buff's stats }) -> SigById[SIG_<SPEC>] = { Asc, Node, Build }
AscendancyData.SigById = {}
for _, a in ipairs(AscendancyData.List) do
    AscendancyData.ById[a.Id] = a
    if a.Sig then AscendancyData.SigById[a.Sig] = { Asc = a.Id, Node = a.SigNode, Build = a.Build } end
    for _, id in ipairs(a.Nodes) do
        if AscendancyData.Nodes[id] and AscendancyData.Nodes[id].Type == "AscStart" then a.Start = id end
    end
    AscendancyData.ByClass[a.Class] = AscendancyData.ByClass[a.Class] or {}
    table.insert(AscendancyData.ByClass[a.Class], a)
end
-- children lists (the mini-tree is a tree: every node has one parent)
for id, n in pairs(AscendancyData.Nodes) do
    n.Id = id
    n.Children = n.Children or {}
end
for id, n in pairs(AscendancyData.Nodes) do
    if n.Parent then table.insert(AscendancyData.Nodes[n.Parent].Children, id) end
end

-- Ascendancy points: 2 per TRIAL OF ASCENSION cleared (AscensionTrials; state.AscTrialBest = highest tier), max 8.
-- (until 2026-10-05 they came from Boss Trial tiers; CombatServer carries that progress over once -- LegacyAscBest)
function AscendancyData.PointsFor(state: any): number
    local best = type(state) == "table" and tonumber(state.AscTrialBest) or 0
    return math.min(AscendancyData.MAX_POINTS, math.max(0, math.floor(best)) * AscendancyData.POINTS_PER_TIER)
end
-- the old rule (best Boss Trial tier on any boss, max 4): used once to carry existing players' points over
function AscendancyData.LegacyAscBest(state: any): number
    local best = 0
    local all = type(state) == "table" and type(state.BossTrials) == "table" and state.BossTrials or {}
    for _, p in pairs(all) do
        if type(p) == "table" and type(p.Best) == "number" then best = math.max(best, p.Best) end
    end
    return math.min(4, best)
end
-- points spent = allocated nodes other than the start
function AscendancyData.Spent(state: any): number
    local n = 0
    for _, id in ipairs(type(state) == "table" and state.AscNodes or {}) do
        local node = AscendancyData.Nodes[id]
        if node and node.Type ~= "AscStart" then n += 1 end
    end
    return n
end
-- the player's live ascendancy nodes (only those of their chosen ascendancy count)
function AscendancyData.Active(state: any): { any }
    local out = {}
    local asc = type(state) == "table" and state.Ascendancy or nil
    if not asc then return out end
    for _, id in ipairs(state.AscNodes or {}) do
        local node = AscendancyData.Nodes[id]
        if node and node.Asc == asc then table.insert(out, node) end
    end
    return out
end

return AscendancyData
